func (gate Gate) AdmitRestartLocal(ctx context.Context) (AcceptedIdentity, error) {
	return gate.admitRestartLocal(ctx, gate.verifyRestartBinary)
}

// AdmitIdentityRekeyCompletion admits only the read-only shared-completion probe.
// An owned transition may use its authenticated predecessor without admitting runtime.
func (gate Gate) AdmitIdentityRekeyCompletion(ctx context.Context) (AcceptedIdentity, error) {
	return gate.admitRestartLocal(ctx, func(accepted AcceptedIdentity, roots trust.Keyring) error {
		if err := gate.verifyRestartBinary(accepted, roots); err == nil {
			return nil
		}
		_, err := verifyRecoveryPredecessor("/proc/self/exe", gate.SelfUpdate, roots, accepted)
		return err
	})
}

func (gate Gate) admitRestartLocal(ctx context.Context, verifyBinary func(AcceptedIdentity, trust.Keyring) error) (AcceptedIdentity, error) {
	if gate.Descriptor == nil || gate.Material == nil || gate.Credentials == nil || gate.ObserveIdentity == nil ||
		gate.Markers.directory == "" || !markerDigestRE.MatchString(gate.LoadedControllerConfigSHA256) {
		return AcceptedIdentity{}, fmt.Errorf("%w: required local verifier is absent", ErrAdmission)
	}
	accepted, err := gate.Markers.ReadIdentity()
	if err != nil {
		return AcceptedIdentity{}, fmt.Errorf("read root-owned accepted installation: %w", err)
	}
	inputs, err := gate.acceptedTrustInputs(accepted)
	if err != nil {
		return AcceptedIdentity{}, err
	}
	if err := gate.checkRestartJournal(accepted, inputs); err != nil {
		return AcceptedIdentity{}, err
	}
	descriptor, err := gate.Descriptor.FetchDescriptor(ctx)
	if err != nil {
		return AcceptedIdentity{}, fmt.Errorf("read accepted local slot: %w", err)
	}
	instance, err := gate.Descriptor.FetchInstanceID(ctx)
	if err != nil {
		return AcceptedIdentity{}, fmt.Errorf("read accepted local instance ID: %w", err)
	}
	if descriptor.SchemaVersion != 1 || descriptor.Slot != accepted.Slot || instance != accepted.InstanceOCID {
		return AcceptedIdentity{}, fmt.Errorf("%w: IMDS slot or instance differs from accepted installation", ErrAdmission)
	}
	if err := verifyBinary(accepted, inputs.Roots.Historical); err != nil {
		return AcceptedIdentity{}, err
	}
	if err := VerifyAcceptedLocalIdentity(accepted, gate.ObserveIdentity); err != nil {
		return AcceptedIdentity{}, fmt.Errorf("verify accepted broker/store identity: %w", err)
	}
	pins, err := gate.Material.RestartPins(accepted, inputs.Roots.Historical)
	if err != nil {
		return AcceptedIdentity{}, fmt.Errorf("read accepted material generation: %w", err)
	}
	if err := gate.restartConfig(&pins, accepted); err != nil {
		return AcceptedIdentity{}, err
	}
	if err := gate.Material.VerifyRestart(ctx, accepted, pins); err != nil {
		return AcceptedIdentity{}, fmt.Errorf("verify installed controller material: %w", err)
	}
	if err := gate.Credentials.VerifyLiveCredentials(ctx, pins, accepted); err != nil {
		return AcceptedIdentity{}, fmt.Errorf("verify live controller credentials: %w", err)
	}
	if err := ctx.Err(); err != nil {
		return AcceptedIdentity{}, err
	}
	if err := gate.checkAcceptedUnchanged(accepted); err != nil {
		return AcceptedIdentity{}, err
	}
	if err := verifyBinary(accepted, inputs.Roots.Historical); err != nil {
		return AcceptedIdentity{}, err
	}
	return accepted, nil
}

func (gate Gate) acceptedTrustInputs(accepted AcceptedIdentity) (TrustInputs, error) {
	if gate.trustStore != nil {
		return gate.trustStore.loadTrustInputs(accepted)
	}
	return LoadTrustInputs(accepted)
}

func (gate Gate) checkRestartJournal(accepted AcceptedIdentity, inputs TrustInputs) error {
	_, err := gate.Markers.verifiedIdentityRekey(accepted, inputs)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	return err
}

func (gate Gate) checkAcceptedUnchanged(accepted AcceptedIdentity) error {
	current, err := gate.Markers.ReadIdentity()
	if err != nil {
		return err
	}
	before, err := EncodeAcceptedIdentity(accepted)
	if err != nil {
		return err
	}
	after, err := EncodeAcceptedIdentity(current)
	if err != nil || !bytes.Equal(before, after) {
		return fmt.Errorf("%w: root-owned accepted installation changed during admission", ErrAdmission)
	}
	inputs, err := gate.acceptedTrustInputs(current)
	if err != nil {
		return err
	}
	return gate.checkRestartJournal(current, inputs)
}

func (gate Gate) verifyRestartBinary(accepted AcceptedIdentity, roots trust.Keyring) error {
	binary, err := gate.binaryChecker().VerifyAccepted(accepted.Binary)
	if err == nil && binary.SHA256 == accepted.Binary.SHA256 && binary.Bytes == accepted.Binary.Size &&
		binary.Architecture == accepted.Binary.Architecture {
		return nil
	}
	if err == nil {
		err = ErrRunningBinaryMismatch
	}
	if errors.Is(err, ErrRunningBinaryMismatch) && gate.SelfUpdate.Root != "" {
		_, err = gate.binaryChecker().VerifySelfUpdated(gate.SelfUpdate, roots, release.UpdateExpectation{
			Environment: accepted.Environment, Cell: accepted.Cell, Architecture: accepted.Binary.Architecture,
		})
		if err == nil {
			return nil
		}
	}
	return fmt.Errorf("%w: installed executable differs: %v", ErrAdmission, err)
}

func (gate Gate) AdmitRestart(ctx context.Context) (AcceptedIdentity, error) {
	if gate.Instances == nil {
		return AcceptedIdentity{}, fmt.Errorf("%w: authenticated OCI instance observer is absent", ErrAdmission)
	}
	if _, err := gate.checkedNow(); err != nil {
		return AcceptedIdentity{}, err
	}
	accepted, err := gate.AdmitRestartLocal(ctx)
	if err != nil {
		return AcceptedIdentity{}, err
	}
	observed, err := gate.Instances.ObserveInstance(ctx, accepted.InstanceOCID)
	if err != nil {
		return AcceptedIdentity{}, fmt.Errorf("observe accepted OCI instance: %w", err)
	}
	if observed.InstanceOCID != accepted.InstanceOCID || observed.ImageOCID != accepted.ImageOCID ||
		observed.PrimaryVNICOCID != accepted.PrimaryVNICOCID || observed.PrimaryPrivateIP != accepted.PrimaryPrivateIP ||
		!observed.PrimaryVNIC || observed.LifecycleState != "RUNNING" {
		return AcceptedIdentity{}, fmt.Errorf("%w: authenticated OCI physical identity differs from accepted installation", ErrAdmission)
	}
	if _, err := gate.checkedNow(); err != nil {
		return AcceptedIdentity{}, err
	}
	if err := ctx.Err(); err != nil {
		return AcceptedIdentity{}, err
	}
	if err := gate.checkAcceptedUnchanged(accepted); err != nil {
		return AcceptedIdentity{}, err
	}
	return accepted, nil
}

// restartConfig binds loaded bytes to the accepted baseline or its verified renewal.
func (gate Gate) restartConfig(pins *MaterialPins, accepted AcceptedIdentity) error {
	want, err := pins.controllerConfigSHA256(accepted)
	if err != nil {
		return fmt.Errorf("%w: %w", ErrAdmission, err)
	}
	if want != gate.LoadedControllerConfigSHA256 ||
		len(gate.LoadedControllerConfig) != 0 && digest(gate.LoadedControllerConfig) != want {
		return fmt.Errorf("%w: loaded controller config differs from accepted installation", ErrAdmission)
	}
	pins.config = gate.LoadedControllerConfig
	return nil
}

func (store bakedStore) loadTrustInputs(accepted AcceptedIdentity) (TrustInputs, error) {
	if err := accepted.Validate(); err != nil {
		return TrustInputs{}, err
	}
	genesis, err := store.loadRoots()
	if err != nil {
		return TrustInputs{}, err
	}
	chain, err := readAcceptedRootChain(store.chainFile)
	if err != nil {
		return TrustInputs{}, err
	}
	identity := trust.ChainIdentity{DeploymentID: accepted.DeploymentID, Environment: accepted.Environment,
		Cell: strings.ToLower(accepted.Cell)}
	roots, err := trust.VerifyRootChain(genesis, identity, chain)
	if err != nil {
		return TrustInputs{}, fmt.Errorf("verify accepted deployment root lineage: %w", err)
	}
	return TrustInputs{ChainIdentity: identity, Genesis: genesis, Chain: chain, Roots: roots}, nil
}

// The adopted chain is service-owned signed public state. It has no root-owner
// requirement, but indirect or damaged state cannot become a genesis fallback.
func readAcceptedRootChain(path string) (trust.RootChain, error) {
	if path == "" {
		return trust.RootChain{Version: 1}, nil
	}
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return trust.RootChain{}, ErrBakedInputs
	}
	dir, err := unix.Open("/", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return trust.RootChain{}, err
	}
	for component := range strings.SplitSeq(strings.TrimPrefix(filepath.Dir(path), "/"), "/") {
		if component == "" {
			continue
		}
		next, err := unix.Openat(dir, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
		unix.Close(dir)
		if err != nil {
			if errors.Is(err, os.ErrNotExist) {
				return trust.RootChain{Version: 1}, nil
			}
			return trust.RootChain{}, err
		}
		dir = next
	}
	defer unix.Close(dir)
	fd, err := unix.Openat(dir, filepath.Base(path), unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if errors.Is(err, os.ErrNotExist) {
		return trust.RootChain{Version: 1}, nil
	}
	if err != nil {
		return trust.RootChain{}, err
	}
	file := os.NewFile(uintptr(fd), filepath.Base(path))
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG || stat.Nlink != 1 ||
		stat.Mode&0o7777 != 0o600 && stat.Mode&0o7777 != 0o644 || stat.Size <= 0 || stat.Size > trust.MaxRootChainBytes {
		return trust.RootChain{}, ErrBakedInputs
	}
	wire, err := io.ReadAll(io.LimitReader(file, trust.MaxRootChainBytes+1))
	if err != nil {
		return trust.RootChain{}, err
	}
	return trust.DecodeRootChain(wire)
}

func (store bakedStore) loadRoots() (trust.Keyring, error) {
	rootsDir, err := store.openDirectory(filepath.Join(store.directory, "trust-roots"))
	if err != nil {
		return nil, fmt.Errorf("open baked trust roots: %w", err)
	}
	file := os.NewFile(uintptr(rootsDir), "trust-roots")
	defer file.Close()
	names, err := file.Readdirnames(-1)
	if err != nil {
		return nil, fmt.Errorf("read baked root entries: %w", err)
	}
	if len(names) == 0 || len(names) > MaxRootFiles {
		return nil, ErrBakedInputs
	}
	sort.Strings(names)
	keys := make([]ed25519.PublicKey, 0, len(names))
	total := 0
	for _, name := range names {
		if !rootFilenameRE.MatchString(name) || name == "000.pem" {
			return nil, ErrBakedInputs
		}
		wire, err := store.readFile(rootsDir, name, MaxRootBytes)
		if err != nil {
			return nil, fmt.Errorf("read baked root %s: %w", name, err)
		}
		total += len(wire)
		if total > MaxRootsTotal {
			return nil, ErrBakedInputs
		}
		block, rest := pem.Decode(wire)
		if block == nil || block.Type != "PUBLIC KEY" || len(block.Headers) != 0 || len(bytes.TrimSpace(rest)) != 0 {
			return nil, ErrBakedInputs
		}
		publicKey, err := x509.ParsePKIXPublicKey(block.Bytes)
		key, ok := publicKey.(ed25519.PublicKey)
		if err != nil || !ok || len(key) != ed25519.PublicKeySize {
			return nil, ErrBakedInputs
		}
		keys = append(keys, key)
	}
	roots, err := trust.ParseKeyring(keys...)
	if err != nil {
		return nil, fmt.Errorf("assemble unambiguous root key IDs: %w", err)
	}
	return roots, nil
}

func (store bakedStore) openDirectory(path string) (int, error) {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return -1, ErrBakedInputs
	}
	fd, err := unix.Open("/", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return -1, err
	}
	for _, component := range strings.Split(strings.TrimPrefix(path, "/"), "/") {
		if component == "" || component == "." || component == ".." {
			unix.Close(fd)
			return -1, ErrBakedInputs
		}
		next, err := unix.Openat(fd, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
		unix.Close(fd)
		if err != nil {
			return -1, err
		}
		fd = next
		var stat unix.Stat_t
		if err := unix.Fstat(fd, &stat); err != nil ||
			!store.allowUnsafeAncestors && (stat.Uid != 0 || stat.Gid != 0 || stat.Mode&0o777 != 0o755) {
			unix.Close(fd)
			return -1, ErrBakedInputs
		}
	}
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil ||
		stat.Uid != store.ownerUID || stat.Gid != store.ownerGID || stat.Mode&0o777 != 0o755 {
		unix.Close(fd)
		return -1, ErrBakedInputs
	}
	return fd, nil
}

func (store bakedStore) readFile(dir int, name string, maximum int64) ([]byte, error) {
	if strings.Contains(name, "/") || name == "" || maximum <= 0 {
		return nil, ErrBakedInputs
	}
	fd, err := unix.Openat(dir, name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), name)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Uid != store.ownerUID || stat.Gid != store.ownerGID ||
		stat.Mode&0o7777 != 0o444 || stat.Nlink != 1 || stat.Size <= 0 || stat.Size > maximum {
		return nil, ErrBakedInputs
	}
	wire, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil || len(wire) == 0 || int64(len(wire)) > maximum {
		return nil, ErrBakedInputs
	}
	return wire, nil
}

